<?php
declare(strict_types=1);
namespace TNL\Notices;
require_once dirname(__DIR__).'/Mail/MessageBody.php';
final class Board {
 const TAGS=['important'=>'Importante','security'=>'Seguridad','info'=>'Informativo','mandatory'=>'Obligatorio','optional'=>'Opcional'];
 public static function init(\PDO $db): void {$db->exec("CREATE TABLE IF NOT EXISTS notice_publishers(user_id INTEGER PRIMARY KEY); CREATE TABLE IF NOT EXISTS notice_posts(id INTEGER PRIMARY KEY,author TEXT NOT NULL,author_name TEXT NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,tag TEXT NOT NULL,author_pin INTEGER NOT NULL DEFAULT 0,deleted INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL); CREATE TABLE IF NOT EXISTS notice_comments(id INTEGER PRIMARY KEY,post_id INTEGER NOT NULL,author TEXT NOT NULL,author_name TEXT NOT NULL,body TEXT NOT NULL,created_at TEXT NOT NULL); CREATE TABLE IF NOT EXISTS notice_pins(principal TEXT NOT NULL,post_id INTEGER NOT NULL,PRIMARY KEY(principal,post_id)); CREATE TABLE IF NOT EXISTS notice_reads(principal TEXT PRIMARY KEY,last_seen TEXT NOT NULL,last_post_id INTEGER NOT NULL DEFAULT 0)");}
 public static function canPublish(\PDO $db,array $who): bool {self::init($db);if($who['role']==='admin')return true;$q=$db->prepare('SELECT user_id FROM notice_publishers WHERE user_id=?');$q->execute([$who['id']]);return (bool)$q->fetchColumn();}
 public static function grant(\PDO $db,array $who,int $user,bool $allow): void {self::init($db);if($who['role']!=='admin')throw new \InvalidArgumentException('Solo administración gestiona permisos.');$q=$db->prepare('SELECT id FROM users WHERE id=? AND active=1');$q->execute([$user]);if(!$q->fetchColumn())throw new \InvalidArgumentException('Usuario no disponible.');$db->prepare($allow?'INSERT OR IGNORE INTO notice_publishers VALUES(?)':'DELETE FROM notice_publishers WHERE user_id=?')->execute([$user]);}
 public static function content(string $body): string {if(strlen($body)>50000)throw new \InvalidArgumentException('Contenido demasiado largo.');$html=\TNL\Mail\MessageBody::html($body,'html');if(trim(strip_tags($html))===''&&!str_contains($html,'<img'))throw new \InvalidArgumentException('Escribe contenido.');return $html;}
 public static function create(\PDO $db,array $who,string $title,string $body,string $tag,bool $pin): int {if(!self::canPublish($db,$who))throw new \InvalidArgumentException('No tienes permiso para publicar avisos.');$title=trim($title);if($title===''||strlen($title)>180||!isset(self::TAGS[$tag]))throw new \InvalidArgumentException('Título o etiqueta inválidos.');$db->prepare('INSERT INTO notice_posts(author,author_name,title,body,tag,author_pin,created_at) VALUES(?,?,?,?,?,?,?)')->execute([$who['principal'],$who['name'],$title,self::content($body),$tag,$pin?1:0,gmdate('c')]);return (int)$db->lastInsertId();}
 public static function post(\PDO $db,int $id): ?array {self::init($db);$q=$db->prepare('SELECT * FROM notice_posts WHERE id=? AND deleted=0');$q->execute([$id]);return $q->fetch(\PDO::FETCH_ASSOC)?:null;}
 public static function comment(\PDO $db,array $who,int $id,string $body): void {if(!self::post($db,$id))throw new \InvalidArgumentException('Aviso no disponible.');$db->prepare('INSERT INTO notice_comments(post_id,author,author_name,body,created_at) VALUES(?,?,?,?,?)')->execute([$id,$who['principal'],$who['name'],self::content($body),gmdate('c')]);}
 public static function pin(\PDO $db,array $who,int $id,bool $author,bool $on): void {$p=self::post($db,$id);if(!$p)throw new \InvalidArgumentException('Aviso no disponible.');if($author){if($who['principal']!==$p['author']&&$who['role']!=='admin')throw new \InvalidArgumentException('Solo el autor o administración fija para todos.');$db->prepare('UPDATE notice_posts SET author_pin=? WHERE id=?')->execute([$on?1:0,$id]);}else $db->prepare($on?'INSERT OR IGNORE INTO notice_pins(principal,post_id) VALUES(?,?)':'DELETE FROM notice_pins WHERE principal=? AND post_id=?')->execute([$who['principal'],$id]);}
 public static function seen(\PDO $db,string $principal): void {self::init($db);$db->prepare('INSERT INTO notice_reads(principal,last_seen,last_post_id) VALUES(?,?,(SELECT COALESCE(max(id),0) FROM notice_posts)) ON CONFLICT(principal) DO UPDATE SET last_seen=excluded.last_seen,last_post_id=excluded.last_post_id')->execute([$principal,gmdate('c')]);}
 public static function unread(\PDO $db,string $principal): int {self::init($db);$q=$db->prepare("SELECT count(*) FROM notice_posts WHERE deleted=0 AND author<>? AND id>COALESCE((SELECT last_post_id FROM notice_reads WHERE principal=?),0)");$q->execute([$principal,$principal]);return (int)$q->fetchColumn();}
}
